  upload(req, res, (err) => {
    if(err){
      return res.status(500).send('Error uploading file.');
    }
    if(req.file == undefined){
      return res.status(400).send('No file selected.');
    }
    res.send('File uploaded successfully.');
  });
});

app.listen(PORT, () => {
  console.log(`Server started on port ${PORT}`);
});
```

