const CookieManager = {
  // Get all cookies as an object
  getAllCookies: function() {
    return document.cookie.split('; ').reduce((cookies, cookieStr) => {
      const [name, ...rest] = cookieStr.split('=');
      cookies[name] = rest.join('=');
      return cookies;
    }, {});
  },

  // Get a specific cookie by name
  getCookie: function(name) {
    const cookies = this.getAllCookies();
    return cookies[name] || null;
  },

  // Set a cookie with optional attributes
  setCookie: function(name, value, days = 7, path = '/') {
    const expires = new Date(Date.now() + days * 864e5).toUTCString();
    document.cookie = `${name}=${value}; expires=${expires}; path=${path}`;
  },

  // Delete a cookie by setting its expiry date to the past
  deleteCookie: function(name, path = '/') {
    document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=${path}`;
  }
};

// Example usage:
// View all cookies
console.log(CookieManager.getAllCookies());

// Get a specific cookie
console.log(CookieManager.getCookie('myCookie'));

// Set a cookie
CookieManager.setCookie('myCookie', 'myValue', 7);

// Delete a cookie
CookieManager.deleteCookie('myCookie');
```

