Certainly! Below is a C++ code snippet that demonstrates how to open a network port on a computer to allow incoming connections for testing purposes. This example uses the Berkeley sockets API, which is widely supported on Unix-like systems (Linux, macOS). For Windows, minor adjustments are needed (like including Winsock headers and initializing Winsock).

The function `openPort` takes the protocol ("tcp" or "udp") and the port number as parameters and sets up a socket to listen for incoming connections or datagrams.

```cpp
#include <iostream>
#include <string>
#include <cstring>      // For memset
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>     // For close()

// Function to open a network port for incoming connections
// protocol: "tcp" or "udp"
// port: port number to open
// Returns socket file descriptor on success, -1 on failure
int openPort(const std::string& protocol, int port) {
    int sockfd;
    int opt = 1;

    if (protocol != "tcp" && protocol != "udp") {
        std::cerr << "Unsupported protocol: " << protocol << std::endl;
        return -1;
    }

    int type = (protocol == "tcp") ? SOCK_STREAM : SOCK_DGRAM;

    // Create socket
    sockfd = socket(AF_INET, type, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Allow reuse of address and port
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return -1;
    }

    // Bind socket to the specified port on all interfaces
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    addr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    if (protocol == "tcp") {
        // Listen for incoming connections
        if (listen(sockfd, 5) < 0) {
            perror("listen");
            close(sockfd);
            return -1;
        }
        std::cout << "TCP port " << port << " is open and listening." << std::endl;
    } else {
        std::cout << "UDP port " << port << " is open and ready to receive datagrams." << std::endl;
    }

    return sockfd;
}

int main() {
    // Example usage:
    int tcpSock = openPort("tcp", 8080);
    if (tcpSock < 0) {
        std::cerr << "Failed to open TCP port 8080" << std::endl;
    }

    int udpSock = openPort("udp", 9090);
    if (udpSock < 0) {
        std::cerr << "Failed to open UDP port 9090" << std::endl;
    }

    // Keep the program running to maintain the open ports
    std::cout << "Press Enter to exit and close sockets..." << std::endl;
    std::cin.get();

    if (tcpSock >= 0) close(tcpSock);
    if (udpSock >= 0) close(udpSock);

    return 0;
}
```

Explanation:
- The function `openPort` creates a socket for the specified protocol and port.
- It sets the socket option `SO_REUSEADDR` to allow quick reuse of the port.
- It binds the socket to all network interfaces on the specified port.
- For TCP, it calls `listen` to accept incoming connections.
- For UDP, it just binds the socket to receive datagrams.
- The function returns the socket file descriptor so you can manage or close it later.
- The example `main` function demonstrates opening TCP port 8080 and UDP port 9090 and keeps the program running until the user presses Enter.

Note:
- This code is for Unix-like systems. For Windows, you need to include `<winsock2.h>`, initialize Winsock with `WSAStartup`, and use `closesocket` instead of `close`.
- Running this program may require administrative privileges depending on the port number and system configuration.
- This code does not implement firewall rules; it only opens sockets on the local machine. To allow external connections, ensure your firewall allows traffic on these ports.

