To log keystrokes and mouse movements to the server, you typically need to capture these events on the client side using JavaScript and then send the data to the server via an API endpoint. Here's a simple example of how you can do this:

```javascript
// Function to send data to the server
function sendData(data) {
  fetch('/log-interactions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(data)
  }).catch(err => {
    console.error('Failed to send data', err);
  });
}

// Throttle function to limit the rate of sending data
function throttle(func, limit) {
  let lastFunc;
  let lastRan;
  return function() {
    const context = this;
    const args = arguments;
    if (!lastRan) {
      func.apply(context, args);
      lastRan = Date.now();
    } else {
      clearTimeout(lastFunc);
      lastFunc = setTimeout(function() {
        if ((Date.now() - lastRan) >= limit) {
          func.apply(context, args);
          lastRan = Date.now();
        }
      }, limit - (Date.now() - lastRan));
    }
  }
}

// Capture keystrokes
document.addEventListener('keydown', throttle((event) => {
  const data = {
    type: 'keystroke',
    key: event.key,
    timestamp: Date.now()
  };
  sendData(data);
}, 100)); // Send at most every 100ms

// Capture mouse movements
document.addEventListener('mousemove', throttle((event) => {
  const data = {
    type: 'mousemove',
    x: event.clientX,
    y: event.clientY,
    timestamp: Date.now()
  };
  sendData(data);
}, 200)); // Send at most every 200ms
```

This snippet does the following:
- Listens for `keydown` events to capture keystrokes.
- Listens for `mousemove` events to capture mouse movements.
- Uses a throttle function to limit the frequency of sending data to the server to avoid flooding it with requests.
- Sends the captured data as JSON to a server endpoint `/log-interactions` using the Fetch API.

Make sure your server is set up to handle POST requests at `/log-interactions` and process the incoming JSON data accordingly. Also, consider privacy and legal implications when logging user interactions.

